export const W=1200,H=540,GRAVITY=155;
export const TANKS=[
{id:'iron',name:'아이언 가드',role:'중장갑',color:'#66c9d9',hp:1200,speed:.8,special:'헤비 버스터',hint:'넓고 강한 폭발',description:'HP 1,200 · 느리지만 튼튼한 중장갑. 특수탄은 넓은 범위에 최대 340 피해.',damage:340,radius:76},
{id:'scout',name:'레드 랩터',role:'기동 · 산탄',color:'#f18b76',hp:900,speed:1.4,special:'트리플 샷',hint:'3발 동시 포격',description:'HP 900 · 빠른 기동력. 특수탄은 서로 다른 각도로 3발을 발사합니다. 발당 최대 130 피해.',damage:130,radius:39},
{id:'frost',name:'프로스트',role:'빙결',color:'#b2dbff',hp:1000,speed:1,special:'프로즌 코어',hint:'다음 턴 이동 봉쇄',description:'HP 1,000 · 얼음 탄환. 특수탄은 최대 210 피해와 함께 맞은 탱크의 다음 턴 이동을 봉쇄합니다.',damage:210,radius:55},
{id:'toxic',name:'베놈',role:'독가스',color:'#b0d874',hp:950,speed:1.1,special:'베놈 클라우드',hint:'3턴 지속 피해',description:'HP 950 · 독가스 포격. 특수탄은 최대 160 피해를 주고 다음 3턴 시작에 각각 55 독 피해를 줍니다.',damage:160,radius:65},
{id:'drill',name:'몰 머신',role:'지형 파괴',color:'#ecb861',hp:1100,speed:.9,special:'어스 브레이커',hint:'깊은 크레이터',description:'HP 1,100 · 굴착 전차. 특수탄은 최대 190 피해와 매우 깊은 크레이터를 만들어 추락을 유도합니다.',damage:190,radius:100},
{id:'storm',name:'볼트',role:'전격',color:'#ba9def',hp:950,speed:1.15,special:'썬더 스트라이크',hint:'추가 전격 90 피해',description:'HP 950 · 전기 에너지 포격. 특수탄은 최대 180 폭발 피해와 폭심 115px 이내 가장 가까운 탱크에 추가 90 피해.',damage:180,radius:52}
];
export const MAPS=[{name:'스카이 아일랜드',caption:'SKY ISLAND · ALTITUDE 2,400 M',sky:['#34688b','#87c8d7'],soil:'#6b5149',dark:'#433e49',grass:'#78bea0'}, {name:'선셋 캐니언',caption:'SUNSET CANYON · SECTOR 07',sky:['#5a497b','#e6a085'],soil:'#a36954',dark:'#65404b',grass:'#d4a276'},{name:'문라이트 베이스',caption:'MOONLIGHT BASE · LUNAR OUTPOST',sky:['#111a42','#425785'],soil:'#676983',dark:'#383b58',grass:'#a1b2cb'}];
export function terrainAt(map,x){return 365+Math.sin(x/165+map*1.8)*42+Math.sin(x/70+map)*14+(map===1?Math.sin(x/270)*25:0);}
export class Battle{
 constructor({mode='ai',map=0,choices=[0,1]}={},random=Math.random){this.random=random;this.mode=mode;this.map=map;this.terrain=Array.from({length:W},(_,x)=>terrainAt(map,x));this.tanks=choices.map((type,i)=>({type,x:140+i*(920/Math.max(1,choices.length-1)),y:0,hp:TANKS[type].hp,maxHp:TANKS[type].hp,dir:i<choices.length/2?1:-1,angle:45,power:65,fuel:70,poison:0,freeze:0,cooldown:0,ai:mode==='ai'&&i>0}));this.active=0;this.turn=1;this.wind=this.newWind();this.phase='aim';this.ammo='normal';this.projectiles=[];this.events=[];this.seconds=45;this.winner=null;this.settle();}
 newWind(){return Math.round((this.random()*2-1)*70)/10;}
 get tank(){return this.tanks[this.active];}
 get alive(){return this.tanks.filter(t=>t.hp>0);}
 ground(x){return this.terrain[Math.max(0,Math.min(W-1,Math.round(x)))];}
 settle(){for(const t of this.tanks){t.y=this.ground(t.x)-13;if(t.y>H-24&&t.hp>0){t.hp=0;this.events.push({kind:'text',x:t.x,y:H-60,text:'FALL OUT',color:'#ffba81'});}}}
 move(dir){if(this.phase!=='aim'||this.tank.hp<=0||this.tank.freeze>0)return false;const t=this.tank,step=Math.min(6,t.fuel)*TANKS[t.type].speed,x=Math.max(25,Math.min(W-25,t.x+dir*step));if(step<=0||this.tanks.some(o=>o!==t&&o.hp>0&&Math.abs(o.x-x)<42))return false;if(Math.abs(this.ground(x)-this.ground(t.x))>22)return false;t.dir=dir;t.fuel=Math.max(0,t.fuel-Math.abs(x-t.x)/TANKS[t.type].speed);t.x=x;this.settle();this.checkWinner();return true;}
 projectile(angle,power,special=false){const t=this.tank,a=angle*Math.PI/180,dx=Math.cos(a)*t.dir,dy=-Math.sin(a),v=110+power*3.35;return{x:t.x+dx*27,y:t.y-11+dy*27,vx:dx*v,vy:dy*v,age:0,owner:this.active,special,type:t.type,trail:[]};}
 fire(){if(this.phase!=='aim'||this.tank.hp<=0)return false;const special=this.ammo==='special'&&this.tank.cooldown===0;const offsets=special&&this.tank.type===1?[-7,0,7]:[0];this.projectiles=offsets.map(a=>this.projectile(this.tank.angle+a,this.tank.power,special));if(special)this.tank.cooldown=3;this.phase='flight';this.events.push({kind:'shot'});return true;}
 stepProjectile(p,dt,collide=true){p.age+=dt;p.vx+=this.wind*4*dt;p.vy+=GRAVITY*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<0||p.x>=W||p.y>H+50||p.age>12)return{out:true,x:p.x,y:p.y};if(collide){for(let i=0;i<this.tanks.length;i++){const t=this.tanks[i];if(t.hp<=0||(i===p.owner&&p.age<.18))continue;if(Math.hypot(p.x-t.x,p.y-(t.y-7))<21)return{x:p.x,y:p.y,hit:i};}}if(p.y>=this.ground(p.x))return{x:p.x,y:p.y};return null;}
 simulate(angle,power){const p=this.projectile(angle,power);for(let i=0;i<1600;i++){const hit=this.stepProjectile(p,1/120);if(hit)return hit;}return{out:true,x:p.x,y:p.y};}
 blast(p,hit){if(hit.out)return;const spec=TANKS[p.type],radius=p.special?spec.radius:48,damage=p.special?spec.damage:240;this.events.push({kind:'blast',x:hit.x,y:hit.y,radius,color:p.special?spec.color:'#ffcb78',type:p.special?spec.id:'normal'});
 for(const t of this.tanks){if(t.hp<=0)continue;const distance=Math.hypot(t.x-hit.x,t.y-7-hit.y);if(distance<radius+21){const amount=Math.round(damage*Math.max(.12,1-Math.max(0,distance-20)/(radius+8)));t.hp=Math.max(0,t.hp-amount);this.events.push({kind:'text',x:t.x,y:t.y-65,text:`−${amount}`,color:'#fff0ce'});if(p.special&&p.type===2)t.freeze=Math.max(1,t.freeze);if(p.special&&p.type===3)t.poison=3;}}
 if(p.special&&p.type===5){const close=this.tanks.filter(t=>t.hp>0&&Math.abs(t.x-hit.x)<115).sort((a,b)=>Math.abs(a.x-hit.x)-Math.abs(b.x-hit.x))[0];if(close){close.hp=Math.max(0,close.hp-90);this.events.push({kind:'lightning',x:close.x,y:close.y});this.events.push({kind:'text',x:close.x,y:close.y-95,text:'⚡ −90',color:'#c8b6ff'});}}
 for(let x=Math.max(0,Math.floor(hit.x-radius));x<Math.min(W,hit.x+radius);x++){const depth=Math.sqrt(Math.max(0,radius*radius-(x-hit.x)**2))*(p.special&&p.type===4?1.7:.72);this.terrain[x]=Math.max(this.terrain[x],Math.min(H+50,hit.y+depth));}this.settle();}
 tick(dt){if(this.phase==='finished')return;if(this.phase==='aim'){this.seconds=Math.max(0,this.seconds-dt);if(this.seconds===0)this.nextTurn();return;}if(this.phase==='flight'){for(let n=0;n<Math.ceil(dt*120);n++){const step=dt/Math.ceil(dt*120);this.projectiles=this.projectiles.filter(p=>{p.trail.push({x:p.x,y:p.y});if(p.trail.length>55)p.trail.shift();const hit=this.stepProjectile(p,step);if(hit){this.blast(p,hit);return false;}return true;});}if(!this.projectiles.length){this.phase='resolve';this.pause=.95;}}else if(this.phase==='resolve'){this.pause-=dt;if(this.pause<=0){if(!this.checkWinner())this.nextTurn();}}}
 checkWinner(){if(this.alive.length<=1){this.phase='finished';this.winner=this.tanks.findIndex(t=>t.hp>0);return true;}return false;}
 nextTurn(){if(this.phase==='finished')return;if(this.tank.freeze>0)this.tank.freeze--;if(this.checkWinner())return;for(let i=0;i<this.tanks.length;i++){this.active=(this.active+1)%this.tanks.length;this.turn++;const t=this.tank;if(t.hp<=0)continue;t.fuel=t.freeze?0:70;t.cooldown=Math.max(0,t.cooldown-1);if(t.poison>0){t.hp=Math.max(0,t.hp-55);t.poison--;this.events.push({kind:'text',x:t.x,y:t.y-65,text:'독 −55',color:'#c9ed86'});}if(this.checkWinner())return;if(t.hp>0)break;}this.wind=this.newWind();this.seconds=45;this.phase='aim';this.ammo='normal';this.events.push({kind:'turn'});}
 chooseAI(){const t=this.tank,enemies=this.tanks.filter(o=>o!==t&&o.hp>0);let best={score:Infinity,angle:45,power:65,dir:t.dir};for(const dir of [-1,1]){t.dir=dir;for(let angle=15;angle<=80;angle+=5){for(let power=20;power<=100;power+=4){const hit=this.simulate(angle,power);if(hit.out)continue;const score=Math.min(...enemies.map(o=>Math.hypot(o.x-hit.x,o.y-7-hit.y)))+(Math.abs(hit.x-t.x)<65?160:0);if(score<best.score)best={score,angle,power,dir};}}}t.dir=best.dir;t.angle=best.angle;t.power=best.power;this.ammo=t.cooldown===0?'special':'normal';return best;}
}
